Înțeleg că funcțiile `splitWord()` și `letterPermute()` generează toate combinările de 2, 3, 4 și 5 litere, fiecare dintre ele permutate în toate modurile posibile. Ce zici de codul ăsta? E mai scurt și mai ușor de verificat că e corect:

``` php
<?php

define('MIN_LENGTH', 2);

$v = ['A', 'B', 'C', 'D', 'E'];
$results = [];

gen($v, 0, $results);
print_r($results);

// Permută pozițiile $k ... |$v|-1
function gen(&$v, $k, &$results) {
  // Primele $k elemente constituie o soluție (peste o limită minimă)
  if ($k >= MIN_LENGTH) {
    $results[] = implode(array_slice($v, 0, $k));
  }

  // Dacă n-am epuizat vectorul, continui
  if ($k < count($v)) {
    // Pe poziția $k pun, pe rând, fiecare din elementele rămase
    for ($i = $k; $i < count($v); $i++) {
      $tmp = $v[$k];
      $v[$k] = $v[$i];
      $v[$i] = $tmp;

      // Reapelez de la poziția $k + 1
      gen($v, $k + 1, $results);

      // Apoi pun elementul inițial la loc
      $tmp = $v[$k];
      $v[$k] = $v[$i];
      $v[$i] = $tmp;
    }
  }
  // Astfel, la final, $v este nemodificat
}
```

